// toArray(root) is the reverse: level order with nulls for gaps, trailing nulls removed.
function toArray(root) {
  const values = [];
  const queue = [root];
  let front = 0;
  while (front < queue.length) {
    const node = queue[front];
    front++;
    if (node === null) {
      values.push(null);
      continue;
    }
    values.push(node.val);
