// ---- End of helpers ----

function levelOrder(root) {
  const levels = [];
  if (root === null) return levels;
  let queue = [root];
  while (queue.length > 0) {
    const values = [];
    const nextQueue = [];
    for (const node of queue) {          // everything in queue is on the same level
      values.push(node.val);
      if (node.left !== null) nextQueue.push(node.left);
      if (node.right !== null) nextQueue.push(node.right);
    }
    levels.push(values);
    queue = nextQueue;
  }
  return levels;
}
